"""Instruments and sound effects made in code (48 kHz stereo-ready mono signals). Nothing recorded, nothing generated by AI.
Mallet, pizzicato, bass, whistle lead, pads, drums, plus cartoon effects (pop, boing, bell, bark, roar, crunch...)."""
import numpy as np
from scipy.signal import butter, sosfilt, lfilter

SR = 48000
rng = np.random.default_rng(2026)


def filt(x, kind, f, order=4):
    return sosfilt(butter(order, f, btype=kind, fs=SR, output="sos"), x).astype(np.float32)


def tt(d):
    return np.arange(max(1, int(d * SR))) / SR


def noise(d):
    return rng.standard_normal(max(1, int(d * SR))).astype(np.float32)


def nrm(x, peak=1.0):
    return (x / (np.abs(x).max() + 1e-9) * peak).astype(np.float32)


def mtof(m):
    return 440.0 * 2 ** ((m - 69) / 12)


def adsr(n, a=0.005, r=0.05, sus=None):
    t = np.arange(n) / SR
    e = np.minimum(1, t / max(a, 1e-4))
    rel = np.clip((n / SR - t) / max(r, 1e-4), 0, 1)
    return (e * rel).astype(np.float32)


def put(buf, sig, t, gain=1.0, pan=0.0):
    """Add a mono signal into a stereo buffer at time t (seconds) with equal-power pan."""
    i = int(round(t * SR))
    l, r = np.cos((pan + 1) * np.pi / 4) * 1.414, np.sin((pan + 1) * np.pi / 4) * 1.414
    if i < 0:
        sig, i = sig[-i:], 0
    j = min(len(buf), i + len(sig))
    if j > i:
        buf[i:j, 0] += sig[: j - i] * gain * l
        buf[i:j, 1] += sig[: j - i] * gain * r


# ---------------------------------------------------------------- instruments
def mallet(m, d=0.6, bright=1.0):
    t = tt(d); f = mtof(m)
    y = np.sin(2 * np.pi * f * t) * np.exp(-t / 0.32) + 0.35 * bright * np.sin(2 * np.pi * 4 * f * t) * np.exp(-t / 0.05) + 0.12 * bright * np.sin(2 * np.pi * 9.8 * f * t) * np.exp(-t / 0.012)
    return (y * adsr(len(t), 0.002, 0.04)).astype(np.float32)


def glock(m, d=0.9):
    t = tt(d); f = mtof(m)
    y = np.sin(2 * np.pi * f * t) * np.exp(-t / 0.45) + 0.3 * np.sin(2 * np.pi * 2.76 * f * t) * np.exp(-t / 0.12) + 0.15 * np.sin(2 * np.pi * 5.4 * f * t) * np.exp(-t / 0.05)
    return (y * adsr(len(t), 0.001, 0.05)).astype(np.float32)


def pluck(m, d=0.5, bright=0.5, decay=0.994):
    f0 = mtof(m); Nd = max(2, int(SR / f0 - 0.5)); n = int(d * SR)
    x = np.zeros(n, np.float32); x[:Nd] = filt(rng.standard_normal(Nd).astype(np.float32), "low", 1200 + 6000 * bright, 2)
    a = np.zeros(Nd + 2); a[0] = 1; a[Nd] = -0.5 * decay; a[Nd + 1] = -0.5 * decay
    y = lfilter([1.0], a, x).astype(np.float32)
    return nrm(y * adsr(n, 0.001, 0.03))


def bass(m, d=0.35):
    t = tt(d); f = mtof(m)
    y = np.sin(2 * np.pi * f * t) + 0.35 * np.sin(2 * np.pi * 2 * f * t) + 0.12 * np.sign(np.sin(2 * np.pi * f * t))
    return (np.tanh(1.4 * y) * np.exp(-t / 0.22) * adsr(len(t), 0.004, 0.04)).astype(np.float32)


def whistle(m, d=0.4, vib=0.012):
    t = tt(d); f = mtof(m) * (1 + vib * np.sin(2 * np.pi * 5.6 * t) * np.minimum(1, t / 0.15))
    ph = 2 * np.pi * np.cumsum(f) / SR
    y = np.sin(ph) + 0.08 * np.sin(2 * ph) + 0.02 * filt(noise(d), "band", [1800, 5000], 2)
    return (y * adsr(len(t), 0.02, 0.07)).astype(np.float32)


def pad(ms, d, a=0.5, r=0.8, bright=900):
    t = tt(d); y = np.zeros(len(t), np.float32)
    for m in ms:
        for det in (-0.004, 0.0, 0.005):
            f = mtof(m) * (1 + det)
            y += (2 * ((f * t) % 1) - 1).astype(np.float32)
    y = filt(y, "low", bright, 2)
    return (y / (3 * len(ms)) * adsr(len(t), a, r)).astype(np.float32)


def brass(ms, d=0.35):
    t = tt(d); y = np.zeros(len(t), np.float32)
    for m in ms:
        f = mtof(m); y += (2 * ((f * t) % 1) - 1).astype(np.float32)
    cutoff = 400 + 2600 * np.exp(-t / 0.08)
    y = filt(y, "low", 3000, 2) * (0.5 + 0.5 * np.exp(-t / 0.1))
    return nrm(y * adsr(len(t), 0.01, 0.12))


def kick(d=0.32, f0=120, f1=48):
    t = tt(d); f = f1 + (f0 - f1) * np.exp(-t / 0.04)
    return nrm(np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t / 0.12) + 0.2 * filt(noise(d), "low", 900, 2) * np.exp(-t / 0.01))


def snare(d=0.22):
    t = tt(d)
    return nrm(0.8 * filt(noise(d), "band", [1200, 6500], 2) * np.exp(-t / 0.07) + 0.5 * np.sin(2 * np.pi * 190 * t) * np.exp(-t / 0.05))


def clap(d=0.18):
    t = tt(d); e = np.exp(-t / 0.05) + 0.6 * np.exp(-np.maximum(0, t - 0.012) / 0.02) * (t > 0.012)
    return nrm(filt(noise(d), "band", [900, 4500], 2) * e)


def hat(d=0.05):
    t = tt(d); return nrm(filt(noise(d), "high", 7000, 2) * np.exp(-t / 0.012))


def shaker(d=0.08):
    t = tt(d); return nrm(filt(noise(d), "band", [4500, 11000], 2) * np.sin(np.pi * t / d) ** 2)


def tom(m=45, d=0.35):
    t = tt(d); f = mtof(m) * (1 + 0.6 * np.exp(-t / 0.03))
    return nrm(np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t / 0.14) + 0.15 * filt(noise(d), "band", [300, 2000], 2) * np.exp(-t / 0.03))


def cymbal(d=1.4):
    t = tt(d); return nrm(filt(noise(d), "high", 4500, 2) * np.exp(-t / 0.45) * adsr(len(t), 0.002, 0.3))


# ---------------------------------------------------------------- effects
def pop(d=0.09):
    t = tt(d); f = 900 * np.exp(-t / 0.02) + 260
    return nrm(np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t / 0.025) + 0.15 * filt(noise(d), "high", 2000, 2) * np.exp(-t / 0.004))


def whoosh(d=0.5, lo=300, hi=3000):
    t = tt(d); return nrm(filt(noise(d), "band", [lo, hi], 2) * np.sin(np.pi * t / d) ** 2)


def sparkle(d=0.9, base=84, n=9):
    out = np.zeros(int(d * SR), np.float32)
    notes = [base + s for s in (0, 4, 7, 12, 16, 19, 24, 28, 31)][:n]
    for i, m in enumerate(notes):
        s = glock(m, 0.6) * (0.9 - i * 0.05); j = int(i * 0.045 * SR); out[j:j + len(s)] += s[: len(out) - j]
    out += 0.05 * filt(noise(d), "high", 6000, 2) * np.exp(-tt(d) / 0.3)
    return nrm(out)


def ding(m=88, d=1.2):
    t = tt(d); f = mtof(m)
    return nrm(np.sin(2 * np.pi * f * t) * np.exp(-t / 0.5) + 0.4 * np.sin(2 * np.pi * 2.4 * f * t) * np.exp(-t / 0.2) + 0.2 * np.sin(2 * np.pi * 5.9 * f * t) * np.exp(-t / 0.06))


def bell(m=50, d=4.5):
    """A big clock bell: inharmonic partials with long decay."""
    t = tt(d); f = mtof(m)
    parts = [(0.5, 1.0, 2.6), (1.0, 0.8, 2.2), (1.19, 0.6, 1.6), (1.5, 0.5, 1.4), (2.0, 0.45, 1.1), (2.51, 0.3, 0.7), (2.66, 0.25, 0.6), (3.01, 0.2, 0.5), (4.1, 0.15, 0.3)]
    y = sum(a * np.sin(2 * np.pi * f * k * t + rng.random() * 6) * np.exp(-t / tau) for k, a, tau in parts)
    y += 0.3 * filt(noise(d), "band", [400, 3000], 2) * np.exp(-t / 0.02)
    return nrm(y * adsr(len(t), 0.002, 0.4))


def bikebell():
    out = np.zeros(int(0.7 * SR), np.float32)
    for k in (0, 0.16):
        s = ding(98, 0.5); j = int(k * SR); out[j:j + len(s)] += s[: len(out) - j]
    return nrm(out)


def boing(d=0.45, f0=180, f1=520):
    t = tt(d); f = f0 + (f1 - f0) * (t / d) ** 0.6 + 40 * np.sin(2 * np.pi * 22 * t) * np.exp(-t / 0.2)
    return nrm(np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t / 0.25) * adsr(len(t), 0.003, 0.05))


def womp(notes=(55, 54, 53, 50), each=0.32):
    """Sad trombone: sliding saw notes with a lowpass and vibrato on the last."""
    out = []
    for i, m in enumerate(notes):
        d = each * (2.2 if i == len(notes) - 1 else 1)
        t = tt(d); f = mtof(m) * (1 + (0.02 * np.sin(2 * np.pi * 6 * t) if i == len(notes) - 1 else 0))
        y = 2 * ((np.cumsum(f) / SR) % 1) - 1
        out.append(filt(y.astype(np.float32), "low", 1100, 2) * adsr(len(t), 0.03, 0.08))
    return nrm(np.concatenate(out))


def honk(ms=(43, 47), d=0.7):
    t = tt(d); y = np.zeros(len(t), np.float32)
    for m in ms:
        f = mtof(m); y += (2 * ((f * t) % 1) - 1).astype(np.float32)
    return nrm(np.tanh(2 * filt(y, "low", 1400, 2)) * adsr(len(t), 0.01, 0.08))


def beep(m=88, d=0.12):
    t = tt(d); return nrm(np.sign(np.sin(2 * np.pi * mtof(m) * t)) * 0.5 * adsr(len(t), 0.003, 0.02))


def kaching():
    out = np.zeros(int(1.0 * SR), np.float32)
    s1 = filt(noise(0.08), "band", [2000, 7000], 2) * np.exp(-tt(0.08) / 0.015); out[: len(s1)] += s1
    for k, m in ((0.06, 100), (0.11, 105)):
        s = ding(m, 0.8) * 0.8; j = int(k * SR); out[j:j + len(s)] += s[: len(out) - j]
    return nrm(out)


def scratch(d=1.0, rate=7, lo=1500, hi=6000):
    """Pencil or crayon on paper: filtered noise in strokes."""
    t = tt(d); strokes = 0.5 + 0.5 * np.sin(2 * np.pi * rate * t + 2 * np.sin(2 * np.pi * 1.3 * t))
    y = filt(noise(d), "band", [lo, hi], 2) * strokes ** 1.5
    return nrm(y * adsr(len(t), 0.03, 0.06))


def squeak(d=1.0):
    t = tt(d); f = 1400 + 500 * np.sin(2 * np.pi * 9 * t)
    y = np.sin(2 * np.pi * np.cumsum(f) / SR) * (0.5 + 0.5 * np.sign(np.sin(2 * np.pi * 9 * t)))
    return nrm(filt(y.astype(np.float32), "band", [900, 3500], 2) * adsr(len(t), 0.02, 0.05))


def knock(f=300, d=0.18, low=110):
    t = tt(d)
    return nrm(filt(noise(d), "band", [f * 0.6, f * 1.6], 2) * np.exp(-t / 0.03) + 0.8 * np.sin(2 * np.pi * low * t) * np.exp(-t / 0.05))


def slam():
    t = tt(0.6)
    return nrm(knock(220, 0.6, 70) + 0.6 * filt(noise(0.6), "low", 500, 3) * np.exp(-t / 0.12) + 0.4 * np.sin(2 * np.pi * 52 * t) * np.exp(-t / 0.2))


def click():
    t = tt(0.06); return nrm(filt(noise(0.06), "band", [2500, 8000], 2) * np.exp(-t / 0.004) + 0.5 * np.sin(2 * np.pi * 1800 * t) * np.exp(-t / 0.006))


def clink(m=96):
    s = ding(m, 0.35) * 0.7
    c = click(); s[: len(c)] += 0.5 * c
    return nrm(s)


def steps(times, f=230, low=95):
    d = (max(times) if times else 0) + 0.3
    out = np.zeros(int(d * SR), np.float32)
    for k, x in enumerate(times):
        s = knock(f + 30 * (k % 2), 0.2, low) * (0.75 + 0.25 * (k % 2)); i = int(x * SR); out[i:i + len(s)] += s[: len(out) - i]
    return nrm(out)


def clanks(times):
    d = (max(times) if times else 0) + 0.4
    out = np.zeros(int(d * SR), np.float32)
    for k, x in enumerate(times):
        s = ding(80 + (k % 3) * 3, 0.3) * 0.6 + knock(500, 0.3, 140) * 0.5; i = int(x * SR); out[i:i + len(s)] += s[: len(out) - i]
    return nrm(out)


def crowd(d, density=1.0):
    out = np.zeros(int(d * SR), np.float32); x = 0.0
    while x < d - 0.25:
        s = clap(); i = int(x * SR); out[i:i + len(s)] += s[: len(out) - i] * (0.4 + 0.6 * rng.random())
        x += (0.03 + 0.09 * rng.random()) / density
    return nrm(out * adsr(len(out), 0.15, 0.4))


def roar(d=1.6):
    t = tt(d); f = 70 + 30 * np.sin(2 * np.pi * 7 * t) + 40 * np.exp(-t / 0.3)
    growl = np.tanh(3 * np.sin(2 * np.pi * np.cumsum(f) / SR)) * (0.6 + 0.4 * np.sin(2 * np.pi * 23 * t))
    y = 0.8 * growl + 0.9 * filt(noise(d), "band", [150, 1600], 2) * (0.5 + 0.5 * np.sin(2 * np.pi * 11 * t))
    return nrm(filt(y.astype(np.float32), "low", 2500, 2) * np.sin(np.pi * np.minimum(1, t / d)) ** 0.4 * adsr(len(t), 0.05, 0.3))


def crunch(d=0.7):
    out = np.zeros(int(d * SR), np.float32)
    for k in range(10):
        s = knock(400 + rng.random() * 900, 0.2, 90 + rng.random() * 60); i = int((rng.random() ** 2) * 0.25 * SR); out[i:i + len(s)] += s[: len(out) - i] * (1 - k * 0.06)
    out += 0.6 * filt(noise(d), "band", [600, 5000], 2) * np.exp(-tt(d) / 0.1)
    return nrm(out)


def chomp():
    t = tt(0.25); return nrm(knock(260, 0.25, 90) + 0.5 * filt(noise(0.25), "band", [300, 2000], 2) * np.exp(-t / 0.04))


def tear(d=0.9):
    t = tt(d); y = filt(noise(d), "band", [800, 7000], 2) * (0.5 + 0.5 * (rng.random(len(t)) < 0.02).astype(np.float32).cumsum() % 2)
    return nrm(y * np.sin(np.pi * t / d) ** 0.5)


def bark(d=0.22, f0=520):
    t = tt(d); f = f0 * (1 + 0.5 * np.exp(-t / 0.03)) * (1 - 0.35 * t / d)
    tone = np.tanh(2.5 * np.sin(2 * np.pi * np.cumsum(f) / SR))
    y = filt((0.8 * tone + 0.6 * noise(d)).astype(np.float32), "band", [400, 2600], 2)
    return nrm(y * np.exp(-t / 0.07) * adsr(len(t), 0.004, 0.03))


def yip(d=0.16):
    return bark(d, 900)


def flap(d=0.45):
    t = tt(d); y = filt(noise(d), "band", [250, 3500], 2) * (0.5 + 0.5 * np.sign(np.sin(2 * np.pi * 6 * t))) * np.exp(-t / 0.2)
    return nrm(y)


def fire(d):
    t = tt(d); n = len(t)
    crack = (rng.random(n) < 30 / SR).astype(np.float32) * rng.random(n).astype(np.float32)
    y = filt(noise(d), "low", 900, 2) * 0.8 + filt(crack, "band", [1500, 6000], 2) * 4
    return nrm(y * adsr(n, 0.08, 0.2))


def tick(hi=True):
    t = tt(0.05); f = 2600 if hi else 2000
    return nrm(np.sin(2 * np.pi * f * t) * np.exp(-t / 0.006) + 0.3 * filt(noise(0.05), "high", 3000, 2) * np.exp(-t / 0.003))


def crickets(d):
    t = tt(d); y = np.zeros(len(t), np.float32)
    for k, f in enumerate((4300, 4700)):
        gate = (np.sin(2 * np.pi * (2.2 + k * 0.4) * t) > 0.6).astype(np.float32) * (0.5 + 0.5 * np.sign(np.sin(2 * np.pi * 45 * t)))
        y += np.sin(2 * np.pi * f * t) * gate
    return nrm(y * adsr(len(t), 0.2, 0.3))


def wind(d):
    t = tt(d); return nrm(filt(noise(d), "band", [200, 900], 2) * (0.6 + 0.4 * np.sin(2 * np.pi * 0.3 * t)) * adsr(len(t), 0.4, 0.5))


def swish(d=0.6):
    t = tt(d); f = 600 + 2400 * (t / d)
    return nrm(filt(noise(d), "band", [500, 4000], 2) * np.sin(np.pi * t / d) ** 2)


def rise(d=1.2, lo=200, hi=5000):
    t = tt(d); y = filt(noise(d), "band", [lo, hi], 2) * (t / d) ** 2
    return nrm(y * adsr(len(t), 0.01, 0.05))


def slidewhistle(d=0.6, m0=84, m1=72):
    t = tt(d); m = m0 + (m1 - m0) * (t / d); f = 440 * 2 ** ((m - 69) / 12)
    return nrm(np.sin(2 * np.pi * np.cumsum(f) / SR) * adsr(len(t), 0.02, 0.06))


def heart():
    return nrm(glock(91, 0.4) + 0.7 * glock(95, 0.4))


def question():
    t = tt(0.3); f = 500 + 500 * (t / 0.3) ** 2
    return nrm(np.sin(2 * np.pi * np.cumsum(f) / SR) * adsr(len(t), 0.01, 0.05))


def hit(low=40):
    """An orchestral sting: low boom + brass stab + cymbal."""
    t = tt(1.2)
    y = kick(1.2, 90, 36) * 1.0 + 0.6 * brass([low + 12, low + 15, low + 19, low + 24], 1.2) + 0.3 * cymbal(1.2)
    return nrm(y)
